/**
 * State kept once per test window. Cypress bundles the support file and each spec separately, so a
 * module both import runs twice and a plain module-level variable exists twice: the support file
 * would reset its copy before each test while the spec writes to the other. What must be one thing
 * (the step log, the cookie banner's once-per-test flag, the queries registered) lives here, on the
 * window both bundles run in: shared('steps', () => []).
 */
export function shared<T>(key: string, create: () => T): T {
  const store = ((globalThis as { __suiteBuilder?: Record<string, unknown> }).__suiteBuilder ??= {});
  if (!(key in store)) store[key] = create();
  return store[key] as T;
}
